add('headline','''R{display:flex;flex-direction:column;justify-content:center;gap:var(--gap);padding:var(--pad);border-left:8px solid var(--a1)}R h2{font-family:var(--font-display);font-size:var(--type-48);font-weight:var(--title-weight);letter-spacing:var(--title-track);line-height:var(--title-line)}R h2 b{color:var(--a1);font-weight:inherit}R.big h2{font-size:var(--type-64)}R.center{align-items:center;text-align:center;border-left:0;border-top:2px solid var(--a1)}R.on{background:var(--a1);border-color:var(--a1);color:var(--a1-on)}R.on :is(h2 b,.note,.kick){color:var(--a1-on)}@container(max-width:600px){R h2,R.big h2{font-size:var(--type-36)}}@container(max-height:260px){R h2,R.big h2{font-size:var(--type-28)}}''')
