add('chart-donut','''R.donuts{display:flex;align-items:center;justify-content:space-around;gap:var(--gap)}R.donut{aspect-ratio:1;max-height:100%;max-width:100%;position:relative;flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:var(--pad);border-radius:999px;background:conic-gradient(var(--a1) calc(var(--v)*1%),var(--n-2) 0)}R.donut::before{content:'';position:absolute;inset:16%;border-radius:999px;background:var(--page);z-index:-1}R.donut>.fig{font-size:var(--type-48)}R.donut>.name{font-size:var(--type-20);max-width:60%;text-align:center}R.donut:only-child{width:440px;justify-self:center;align-self:center}R.donuts>.donut{width:auto;height:auto;flex-basis:0}R.donuts>.donut .fig{font-size:var(--type-40)}@container(max-width:340px){R.donut>.fig,R.donuts>.donut .fig{font-size:var(--type-28)}R.donut>.name{font-size:var(--type-16)}}''')
