# Geometry generated for 2..12 equal sample positions; each value remains live CSS --v.
for n in range(2,13):
 for i in range(1,n+1):
  x=5+(i-1)*90/(n-1)
  styles['chart-line']+=f'R:has(>.pt:nth-child({n}):last-child)>.pt:nth-child({i})>b,R:has(>.pt:nth-child({n}):last-child)>.pt:nth-child({i})>span{{left:{x:.6f}%}}'
for i in range(1,13):
 styles['chart-line']+=f'R>.pt:nth-child({i})>b{{anchor-name:--anchor-frame-line-{i}}}'
 if i>1:
  a=f'--anchor-frame-line-{i-1}';b=f'--anchor-frame-line-{i}'
